script:
UNWIND $n0 AS p CREATE (x:Article) SET x = p;
UNWIND $n1 AS p CREATE (x:ClientFile) SET x = p;
UNWIND $n2 AS p CREATE (x:FatfScope) SET x = p;
UNWIND $n3 AS p CREATE (x:Institution) SET x = p;
UNWIND $n4 AS p CREATE (x:Law) SET x = p;
UNWIND $n5 AS p CREATE (x:Licence) SET x = p;
UNWIND $n6 AS p CREATE (x:OfficeRecord) SET x = p;
UNWIND $n7 AS p CREATE (x:Regulator) SET x = p;
UNWIND $n8 AS p CREATE (x:Sector) SET x = p;
UNWIND $n9 AS p CREATE (x:SectorCategory) SET x = p;
UNWIND $n10 AS p CREATE (x:SectorDuty) SET x = p;
UNWIND $r0 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:CLIENT_OF]->(b) SET x = r.p;
UNWIND $r1 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:DEFINED_IN]->(b) SET x = r.p;
UNWIND $r2 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:FULFILS]->(b) SET x = r.p;
UNWIND $r3 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:GRANTED_BY]->(b) SET x = r.p;
UNWIND $r4 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:HAS_DUTY]->(b) SET x = r.p;
UNWIND $r5 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:HAS_RECORD]->(b) SET x = r.p;
UNWIND $r6 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:HOLDS]->(b) SET x = r.p;
UNWIND $r7 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:IN_CATEGORY]->(b) SET x = r.p;
UNWIND $r8 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:IN_SCOPE]->(b) SET x = r.p;
UNWIND $r9 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:IN_SECTOR]->(b) SET x = r.p;
UNWIND $r10 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:PART_OF]->(b) SET x = r.p;
UNWIND $r11 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:REQUIRES_LICENCE]->(b) SET x = r.p;
UNWIND $r12 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:SUBJECT_TO]->(b) SET x = r.p;
UNWIND $r13 AS r MATCH (a) WHERE a._vid = r.s MATCH (b) WHERE b._vid = r.t CREATE (a)-[x:SUPERVISES]->(b) SET x = r.p;
CREATE FULLTEXT INDEX doc_text IF NOT EXISTS FOR (n:Document) ON EACH [n.title, n.text];
CREATE FULLTEXT INDEX article_text IF NOT EXISTS FOR (n:Article) ON EACH [n.text_en, n.text_local];
CREATE FULLTEXT INDEX chunk_text IF NOT EXISTS FOR (n:Chunk) ON EACH [n.text];
CREATE CONSTRAINT institution_id IF NOT EXISTS FOR (n:Institution) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT sector_id IF NOT EXISTS FOR (n:Sector) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT category_id IF NOT EXISTS FOR (n:SectorCategory) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT fatf_id IF NOT EXISTS FOR (n:FatfScope) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT regulator_id IF NOT EXISTS FOR (n:Regulator) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT licence_id IF NOT EXISTS FOR (n:Licence) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT law_id IF NOT EXISTS FOR (n:Law) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT article_id IF NOT EXISTS FOR (n:Article) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT duty_id IF NOT EXISTS FOR (n:SectorDuty) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT record_id IF NOT EXISTS FOR (n:OfficeRecord) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT client_file_id IF NOT EXISTS FOR (n:ClientFile) REQUIRE n.id IS UNIQUE;
CREATE CONSTRAINT client_file_case IF NOT EXISTS FOR (n:ClientFile) REQUIRE n.case IS UNIQUE;
CREATE CONSTRAINT counterparty_key IF NOT EXISTS FOR (n:CounterpartyKey) REQUIRE n.key IS UNIQUE;
CREATE CONSTRAINT record_date IF NOT EXISTS FOR (n:OfficeRecord) REQUIRE n.date IS NOT NULL;
CREATE CONSTRAINT record_duty IF NOT EXISTS FOR (n:OfficeRecord) REQUIRE n.duty IS NOT NULL;
CREATE CONSTRAINT client_file_as_of IF NOT EXISTS FOR (n:ClientFile) REQUIRE n.as_of IS NOT NULL;
CREATE CONSTRAINT client_file_file IF NOT EXISTS FOR (n:ClientFile) REQUIRE n.file IS NOT NULL;
CREATE CONSTRAINT counterparty_key_type IF NOT EXISTS FOR (n:CounterpartyKey) REQUIRE n.key :: STRING;
CREATE CONSTRAINT duty_from IF NOT EXISTS FOR (n:SectorDuty) REQUIRE n.valid_from IS NOT NULL;
CREATE CONSTRAINT supervises_aml_type IF NOT EXISTS FOR ()-[r:SUPERVISES]-() REQUIRE r.aml :: BOOLEAN;
CREATE INDEX record_date_idx IF NOT EXISTS FOR (n:OfficeRecord) ON (n.date);
CREATE INDEX client_file_risk IF NOT EXISTS FOR (n:ClientFile) ON (n.risk_band);
CREATE INDEX duty_valid IF NOT EXISTS FOR (n:SectorDuty) ON (n.valid_from, n.valid_to)
